function descrever(valor: string | number): string {
  // aqui valor ainda é string | number
  if (typeof valor === "string") {
    // neste ramo o compilador só conhece string
    return valor.padStart(5, ".");
  }
  // e no ramo restante só conhece number
  return valor.toFixed(2);
}

console.log(descrever("ok")); // "...ok"
console.log(descrever(3.5));  // "3.50"

function inicial(valor: string | number): string {
  // @ts-expect-error fora de qualquer verificação valor continua a ser a união inteira, e number não tem toUpperCase
  return valor.toUpperCase();
}

function inspecionar(valor: string | number | boolean | undefined | (() => number)): string {
  if (typeof valor === "string") return "texto de " + valor.length + " caracteres";
  if (typeof valor === "number") return "numero " + valor.toFixed(1);
  if (typeof valor === "boolean") return valor ? "sim" : "nao";
  if (typeof valor === "function") return "funcao devolveu " + valor();
  // só sobra undefined
  return "sem valor";
}

console.log(inspecionar("ola"));     // "texto de 3 caracteres"
console.log(inspecionar(7));         // "numero 7.0"
console.log(inspecionar(false));     // "nao"
console.log(inspecionar(() => 42));  // "funcao devolveu 42"
console.log(inspecionar(undefined)); // "sem valor"

function contar(valor: string[] | null): number {
  if (typeof valor === "object") {
    // typeof null também devolve "object": aqui valor ainda é string[] | null
    // @ts-expect-error valor pode ser null neste ramo
    return valor.length;
  }
  return 0;
}

console.log(contar(["a", "b"])); // 2
console.log(contar(null));       // 0

function saudacaoTruthy(nome: string | undefined): string {
  // o ramo verdadeiro exclui undefined, mas também exclui a cadeia vazia
  if (nome) {
    return "Ola, " + nome;
  }
  return "Ola, visitante";
}

function saudacaoExplicita(nome: string | undefined): string {
  // aqui só undefined é excluído
  if (nome !== undefined) {
    return "Ola, " + nome;
  }
  return "Ola, visitante";
}

console.log(saudacaoTruthy(""));    // "Ola, visitante"
console.log(saudacaoExplicita("")); // "Ola, "

function desconto(percentagem: number | undefined): string {
  if (percentagem) {
    return percentagem + "%";
  }
  return "sem desconto";
}

console.log(desconto(20)); // "20%"
console.log(desconto(0));  // "sem desconto", embora zero seja um desconto válido

interface Registo {
  autor?: string | null;
}

function autorDe(registo: Registo): string {
  const autor = registo.autor; // string | null | undefined
  // != null apanha null e undefined de uma só vez: aqui autor é string
  if (autor != null) {
    return autor.trim();
  }
  return "anonimo";
}

console.log(autorDe({ autor: "  Ana  " })); // "Ana"
console.log(autorDe({ autor: null }));      // "anonimo"
console.log(autorDe({}));                   // "anonimo"

function coincidem(a: string | number, b: string | boolean): string {
  if (a === b) {
    // string é o único tipo comum aos dois lados: a e b passam ambos a string
    return a.toUpperCase() + b.length;
  }
  return "diferentes";
}

console.log(coincidem("ola", "ola")); // "OLA3"
console.log(coincidem(1, true));      // "diferentes"

interface RespostaErro {
  erro: string;
  codigo: number;
}

interface RespostaOk {
  dados: string[];
}

function resumir(resposta: RespostaErro | RespostaOk): string {
  // só RespostaErro declara a propriedade erro
  if ("erro" in resposta) {
    return "falhou com " + resposta.codigo + ": " + resposta.erro;
  }
  return resposta.dados.length + " resultados";
}

console.log(resumir({ erro: "sem rede", codigo: 503 })); // "falhou com 503: sem rede"
console.log(resumir({ dados: ["a", "b", "c"] }));        // "3 resultados"

interface Perfil {
  nome: string;
  telefone?: string;
}

function contacto(perfil: Perfil): string {
  if ("telefone" in perfil) {
    // in garante que a chave existe, não que o valor esteja preenchido
    // @ts-expect-error telefone continua a poder ser undefined
    return perfil.telefone.trim();
  }
  return "sem contacto";
}

console.log(contacto({ nome: "Ana", telefone: " 912 " })); // "912"
console.log(contacto({ nome: "Rui" }));                    // "sem contacto"

class ErroDeRede extends Error {
  constructor(public readonly estado: number, mensagem: string) {
    super(mensagem);
    this.name = "ErroDeRede";
  }
}

function explicar(erro: unknown): string {
  // a subclasse vem primeiro: um ErroDeRede também passa no teste de Error
  if (erro instanceof ErroDeRede) {
    return "rede " + erro.estado + ": " + erro.message;
  }
  if (erro instanceof Error) {
    return "erro: " + erro.message;
  }
  return "falha desconhecida";
}

console.log(explicar(new ErroDeRede(503, "indisponivel"))); // "rede 503: indisponivel"
console.log(explicar(new Error("rebentou")));               // "erro: rebentou"
console.log(explicar("texto solto"));                       // "falha desconhecida"

interface Ponto {
  x: number;
  y: number;
}

function mostrar(valor: Ponto | string): string {
  // @ts-expect-error Ponto é uma interface: não existe em tempo de execução e não pode estar à direita de instanceof
  if (valor instanceof Ponto) {
    return "ponto";
  }
  return "outro";
}

console.log(mostrar("abc")); // "outro"

let dado: string | number = "inicio";
console.log(dado.toUpperCase()); // "INICIO", aqui dado é string

dado = 42;
console.log(dado.toFixed(1)); // "42.0", a atribuição passou dado a number

// @ts-expect-error o tipo declarado continua a ser string | number e não aceita boolean
dado = true;

function agendar(mensagem: string | undefined): void {
  let atual = mensagem;
  if (atual !== undefined) {
    const imprimir = (): void => {
      // @ts-expect-error atual é reatribuída mais abaixo, por isso dentro da função volta a string | undefined
      console.log(atual.toUpperCase());
    };
    imprimir();
  }
  atual = "fim";
  console.log(atual);
}

function agendarBem(mensagem: string | undefined): void {
  if (mensagem !== undefined) {
    const texto = mensagem; // const: o estreitamento fica gravado no tipo de texto
    const imprimir = (): void => {
      console.log(texto.toUpperCase());
    };
    imprimir();
  }
}

agendar("ola");    // "OLA" e depois "fim"
agendarBem("ola"); // "OLA"

