function etiquetar(valor: string | number | boolean): string {
  if (typeof valor === "string") {
    return "texto(" + valor.length + ")";
  }
  if (typeof valor === "number") {
    return "numero(" + valor.toFixed(2) + ")";
  }
  // já só resta boolean
  return "booleano(" + (valor ? "sim" : "nao") + ")";
}

console.log(etiquetar("curso")); // "texto(5)"
console.log(etiquetar(3));       // "numero(3.00)"
console.log(etiquetar(true));    // "booleano(sim)"

function mostrarPontuacao(pontos: number | undefined, nota: string | undefined): string {
  const parte1 = pontos !== undefined ? pontos + " pontos" : "sem pontuacao";
  const parte2 = nota !== undefined ? "nota: " + nota : "sem nota";
  return parte1 + " | " + parte2;
}

console.log(mostrarPontuacao(10, "bom"));           // "10 pontos | nota: bom"
console.log(mostrarPontuacao(0, ""));               // "0 pontos | nota: "
console.log(mostrarPontuacao(undefined, undefined)); // "sem pontuacao | sem nota"

function primeiroCaractere(texto: string | null | undefined): string {
  // != null trata null e undefined; o comprimento já é regra de negócio
  if (texto != null && texto.length > 0) {
    return texto[0];
  }
  return "?";
}

console.log(primeiroCaractere("ola"));  // "o"
console.log(primeiroCaractere(null));   // "?"
console.log(primeiroCaractere(""));     // "?"

interface Pagamento {
  metodo: string;
  valor: number;
}

interface Transferencia {
  iban: string;
  valor: number;
  referencia?: string | null;
}

function descreverMovimento(movimento: Pagamento | Transferencia): string {
  if ("iban" in movimento) {
    const referencia = movimento.referencia; // string | null | undefined
    const sufixo = referencia != null ? " ref " + referencia : " sem referencia";
    return "transferencia de " + movimento.valor.toFixed(2) + " para " + movimento.iban + sufixo;
  }
  return "pagamento de " + movimento.valor.toFixed(2) + " por " + movimento.metodo;
}

console.log(descreverMovimento({ metodo: "cartao", valor: 12.5 }));
// "pagamento de 12.50 por cartao"
console.log(descreverMovimento({ iban: "PT50", valor: 100, referencia: "A1" }));
// "transferencia de 100.00 para PT50 ref A1"
console.log(descreverMovimento({ iban: "PT50", valor: 100, referencia: null }));
// "transferencia de 100.00 para PT50 sem referencia"

class ErroDeValidacao extends Error {
  constructor(public readonly campo: string, mensagem: string) {
    super(mensagem);
    this.name = "ErroDeValidacao";
  }
}

function relatar(erro: unknown): string[] {
  const linhas: string[] = [];
  const registar = (linha: string): void => {
    linhas.push(linha);
  };

  if (erro instanceof ErroDeValidacao) {
    const detalhe = erro; // const local: o estreitamento sobrevive dentro da função
    const escrever = (): void => {
      registar("campo " + detalhe.campo + ": " + detalhe.message);
    };
    escrever();
    return linhas;
  }

  if (erro instanceof Error) {
    registar("erro " + erro.name + ": " + erro.message);
    return linhas;
  }

  registar("valor lancado que nao e um Error: " + String(erro));
  return linhas;
}

try {
  throw new ErroDeValidacao("email", "formato invalido");
} catch (capturado) {
  console.log(relatar(capturado)); // ["campo email: formato invalido"]
}

try {
  throw new RangeError("fora dos limites");
} catch (capturado) {
  console.log(relatar(capturado)); // ["erro RangeError: fora dos limites"]
}

try {
  throw "texto solto";
} catch (capturado) {
  console.log(relatar(capturado)); // ["valor lancado que nao e um Error: texto solto"]
}
